public:
    int firstMissingPositive(vector<int>& nums) {
        int n = nums.size();
        for (int k = 1; k <= n + 1; ++k) {
            bool found = false;
            for (int x : nums) if (x == k) { found = true; break; }
            if (!found) return k;
        }
        return n + 1;
    }
};

